WITH filtered AS (SELECT id, customer_id, store_id, order_date, status, channel, amount, shipping_fee, LEAST(shipping_fee, discount) AS least_shipping_fee_discount FROM orders WHERE order_date > DATE '2023-09-20'), metrics AS (SELECT id, customer_id, LEAD(shipping_fee) OVER (PARTITION BY store_id ORDER BY least_shipping_fee_discount, id) AS next_shipping_fee, LAG(amount) OVER (PARTITION BY store_id ORDER BY least_shipping_fee_discount, id) AS prev_amount, ROW_NUMBER() OVER (PARTITION BY store_id ORDER BY least_shipping_fee_discount, id) AS row_seq, FIRST_VALUE(channel, TRUE) OVER (PARTITION BY DATE_TRUNC('YEAR', order_date), status ORDER BY shipping_fee, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_channel FROM filtered), filtered_orders AS (SELECT id, customer_id, next_shipping_fee, prev_amount, row_seq, ROUND(next_shipping_fee / prev_amount, 2) AS next_shipping_fee_per_prev_amount FROM metrics WHERE row_seq >= 5), enriched AS (SELECT id, next_shipping_fee, AVG(prev_amount) OVER (PARTITION BY customer_id ORDER BY next_shipping_fee_per_prev_amount, id ROWS BETWEEN 5 PRECEDING AND CURRENT ROW) AS prev_amount_avg_5, LAG(next_shipping_fee_per_prev_amount, 1) OVER (PARTITION BY customer_id ORDER BY row_seq, id) AS prev_next_shipping_fee_per_prev_amount FROM filtered_orders WHERE next_shipping_fee BETWEEN 13 AND 36), kept_keys AS (SELECT id FROM enriched INTERSECT ALL SELECT id FROM orders WHERE amount < 1060), verified AS (SELECT s.* FROM enriched s INNER JOIN kept_keys k ON s.id = k.id), kept_keys_2 AS (SELECT id FROM verified INTERSECT ALL SELECT id FROM orders WHERE channel NOT IN ('web', 'store')), kept_rows AS (SELECT s.* FROM verified s INNER JOIN kept_keys_2 k ON s.id = k.id), not_flagged AS (SELECT s.* FROM kept_rows s WHERE EXISTS (SELECT 1 FROM payments ch WHERE ch.order_id = s.id AND ch.order_id IS NULL)) SELECT id, next_shipping_fee, prev_amount_avg_5, prev_next_shipping_fee_per_prev_amount FROM not_flagged ORDER BY next_shipping_fee DESC, id
